def solve(inp, size):
    centers={}
    for r in range(size):
        for c in range(size):
            v=inp[r][c]
            if v!=0 and v!=3 and all(inp[r+d][c]==3 for d in(-1,1)) and all(inp[r][c+d]==3 for d in(-1,1)):
                centers[(r,c)]=v
    zero_cross=[(r,c) for r in range(size) for c in range(size)
                if inp[r][c]==0 and all(inp[r+d][c]==3 for d in(-1,1)) and all(inp[r][c+d]==3 for d in(-1,1))]
    out=[row[:] for row in inp]
    def beam(r,c,dr,dc,v):
        rr,cc=r+dr,c+dc
        while 0<=rr<size and 0<=cc<size:
            if inp[rr][cc]==3:
                # foreign arm -> stop (do not paint beyond); own arm -> continue
                is_own = (rr,c) in centers and dc!=0 or (r,cc) in centers and dr!=0
                # own arm check: same row (for horizontal) / same col (vertical) as center
                own = (dr==0 and rr==r) or (dc==0 and cc==c)
                if not own: return
            out[rr][cc]=v
            rr+=dr; cc+=dc
    # 1. rows
    for (r,c),v in centers.items():
        beam(r,c,0,-1,v); beam(r,c,0,1,v)
    # 2. zero-cross erases its row and column
    for (r,c) in zero_cross:
        for cc in range(size): out[r][cc]=0
        for rr in range(size): out[rr][c]=0
    # 3. columns
    for (r,c),v in centers.items():
        beam(r,c,-1,0,v); beam(r,c,1,0,v)
    # 4. restore 3s
    for r in range(size):
        for c in range(size):
            if inp[r][c]==3: out[r][c]=3
    return out

